# Cargo.toml na raiz
[workspace]
resolver = "2"
members = ["crates/core", "crates/cli", "crates/server"]

[workspace.dependencies]
tokio   = { version = "1", features = ["full"] }
serde   = { version = "1", features = ["derive"] }
thiserror = "1"

# crates/cli/Cargo.toml herda deps do workspace
[dependencies]
tokio  = { workspace = true }
serde  = { workspace = true }
core   = { path = "../core" }

# Cargo.toml
[features]
default   = ["json"]
json      = ["serde", "serde_json"]
async     = ["tokio"]
postgres  = ["sqlx", "sqlx/postgres"]

[dependencies]
serde      = { version = "1", optional = true }
serde_json = { version = "1", optional = true }
tokio      = { version = "1", optional = true }
sqlx       = { version = "0.7", optional = true, default-features = false }

#[cfg(feature = "json")]
pub fn to_json<T: serde::Serialize>(v: &T) -> String {
    serde_json::to_string(v).unwrap()
}

// benches/parse.rs
use criterion::{black_box, criterion_group, criterion_main, Criterion};

fn parse(input: &str) -> u64 { input.parse().unwrap_or(0) }

fn bench_parse(c: &mut Criterion) {
    c.bench_function("parse u64", |b| {
        b.iter(|| parse(black_box("9876543210")))
    });
}

criterion_group!(benches, bench_parse);
criterion_main!(benches);
